class VulnerableAccount {
    private double balance;

    // ANTI-PATTERN: Direct assignment bypasses setBalance validation!
    public VulnerableAccount(double balance) {
        this.balance = balance; // Allows -99999 at birth!
    }

    public void setBalance(double balance) {
        if (balance >= 0) {
            this.balance = balance;
        }
    }
    public double getBalance() { return balance; }
}

class RobustAccount {
    private double balance;

    // BEST PRACTICE: Reuses setter validation at birth!
    public RobustAccount(double balance) {
        setBalance(balance);
    }

    public void setBalance(double balance) {
        if (balance >= 0) {
            this.balance = balance;
        } else {
            this.balance = 0.0;
        }
    }
    public double getBalance() { return balance; }
}

public class Main {
    public static void main(String[] args) {
        VulnerableAccount bad = new VulnerableAccount(-500.0);
        System.out.println("Vulnerable Balance: $" + bad.getBalance()); // -500.0 (Corrupted!)

        RobustAccount good = new RobustAccount(-500.0);
        System.out.println("Robust Balance: $" + good.getBalance()); // 0.0 (Protected!)
    }
}

