}

class MemberAccount {
    private String username;
    private int loyaltyPoints;

    public MemberAccount(String name, int points) {
        setUsername(name);
        setLoyaltyPoints(points);
    }

    public void setUsername(String name) {
        if (name != null && !name.trim().isEmpty()) {
            this.username = name.trim();
        } else {
            this.username = "Guest";
        }
    }

    public void setLoyaltyPoints(int points) {
        this.loyaltyPoints = points >= 0 ? points : 0;
    }

    public String getUsername() { return username; }
    public int getLoyaltyPoints() { return loyaltyPoints; }
}

public class Main {
    public static void main(String[] args) {
        MemberAccount acc = new MemberAccount(null, -50);
        System.out.println("Member: " + acc.getUsername() + " | Points: " + acc.getLoyaltyPoints());
    }
}

class MovieReview {
    private double[] ratings;

    public MovieReview(double[] ratings) {
        this.ratings = ratings != null ? ratings.clone() : new double[0];
    }

    public double calculateAverage() {
        double sum = 0;
        for (double r : ratings) sum += r;
        return ratings.length > 0 ? sum / ratings.length : 0.0;
    }
}

public class Main {
    public static void main(String[] args) {
        double[] scores = {4.0, 5.0};
        MovieReview review = new MovieReview(scores);
        scores[0] = 1.0; // Sabotage attempt has no effect on cloned array
        System.out.println("Average rating: " + review.calculateAverage());
    }
}

